-- 20261024000000_add_submitted_at — PREPARED 2026-10-24, owner-approved and
-- APPLIED the same day (migrate deploy + migrate status both confirmed).
--
-- Purpose: give the review queue a real submission timestamp instead of using
-- createdAt as the recency signal (src/routes/review.routes.ts:90-93 explains why
-- createdAt was a stand-in: "Neither model has a dedicated submittedAt column").
--
-- This migration was generated by the pooler-safe pattern
--   npx prisma migrate diff --from-url $env:DATABASE_URL --to-schema-datamodel
--     ./prisma/schema.prisma --script
-- and then REDUCED to only the statements belonging to THIS change. The raw diff
-- also contains unrelated pre-existing drift statements (resources foreign keys and
-- indexes, lesson_attachments.file_url, ...) which are deliberately NOT included —
-- following the same exclusion discipline as
-- 20260101000010_add_question_sitting_columns and the other hand-copied migrations.
--
-- Apply (owner-approved only, per the no-production-migration rule):
--   npx prisma migrate deploy
--   npx prisma migrate status
-- Mirror changes in prisma/schema.prisma + review.routes.ts/authoring submit routes
-- write the column (schema + code changes land in the same change-set, so the
-- working tree never runs against a DB missing the columns).
--
-- Statement plan:
--   1. add nullable submitted_at to questions / lesson_versions / internship_reviews
--   2. backfill ONLY rows currently in 'pending_review' (submission time is only
--      meaningful pre-review; approved/rejected history keeps createdAt semantics)
--   3. no defaults, no triggers — writes land in the submit endpoints.

ALTER TABLE "questions" ADD COLUMN "submitted_at" TIMESTAMPTZ;
ALTER TABLE "lesson_versions" ADD COLUMN "submitted_at" TIMESTAMPTZ;
ALTER TABLE "internship_reviews" ADD COLUMN "submitted_at" TIMESTAMPTZ;

UPDATE "questions" SET "submitted_at" = "created_at" WHERE "status" = 'pending_review';
UPDATE "lesson_versions" SET "submitted_at" = "created_at" WHERE "status" = 'pending_review';
UPDATE "internship_reviews" SET "submitted_at" = "created_at" WHERE "status" = 'pending_review';
